export const DATA_16: ListeningTest[] = [
  { id: "listening-46", title: "Đề 46", subtitle: "35 câu · 40 phút", durationMin: 40, parts: [
    { n: 1, title: "Part 1", hint: HINTS[1], recordings: [
      { id: "listening-46-p1", label: "Bài nghe Part 1", audio: "https://cdn.thanhnamnguyen.dev/vstep/audio/listening/listening-03/part1-1.mp3", script: "1. When is the man’s appointment?\nA: Good morning. I’d like someone to cut my hair, please. Can I make an appointment?\nB: Certainly. Wednesday or Thursday morning or Friday afternoon?\nA: On Friday I’m going to go to France. What about Thursday afternoon? I’m afraid I have a meeting all day Wednesday.\nB: Well. It’s a little bit difficult but that’s the only afternoon you can come. So we’ll see you then.\n2. Which is the aunt’s postcard?\nA: Look, Sandra. I’ve got this really nice postcard for my aunt.\nB: Oh what a pretty village. And it’s right by a river. Isn’t it in the mountain?\nA: Yes. But you can’t see them in the picture.\nB: Perhaps, they’re behind those tall trees.\n3. What time will the plane to Milan leave?\nA: Excuse me. What time is the next plane to Milan?\nB: It should leave at 7:15 but an hour late today.\nA: Oh. That’s a problem. If it doesn’t leave until 8:15, I’ll be one hour late for my meeting.\nB: I’m sorry, Sir. There’s nothing I can do.\n4. Which present has the girl bought her mother?\nJane: Hi. It’s me, Jane. I’ve got Mom’s birthday present. I think she’ll like it. ...yes, that’s right, a gold colored one. She’s always writing letters so she’ll find it useful. I thought about a CD but I’m never really sure what music she likes and dad bought her a new pair of earrings for her birthday anyway. I’m sure she’ll like what I’ve got her.\n5. What time will the pie be ready?\nA: What time is it Mom? Do you think the apple pie will be ready yet?\nB: It’s 4:35\nA: And the pie went into the oven at 4:15\nB: That’s right. You could check it at 5:00. And turn the heat down a bit but don’t take out until 20 past. That’s 45 minutes to go.\nA: OK. I’m hungry already.\n6. What time is the swimming lesson today?\nA: Hi Chidy. Do you want to play tennis after school? Say about 4:30\nB: That’s would be fun but I’ve got a swimming lesson. It’s usually at 5:15 but it’s half an hour earlier this evening, at 4:45. It takes me ages to cycle to the swimming pool so I really don’t think I have time today. Let’s try it tomorrow\nA: OK\n7. Which subject does the boy like best?\nBoy: I really like the new IT teacher. Our project for this term is to design a new website. I’ve always wanted to know how to do that. The sports teacher is much more serious. But that’s still my favorite subject. Last year, I usually like geography but the teacher we have now gives us so much homework.\n8. Which T-shirt does the boy decide to buy?\nA: I’d like a buy a black T-shirt with short sleeves, please, large size.\nB: I’m afraid the black one has long sleeves. But we’ve got short sleeves in a lighter color. Do you want a round neck or a V-neck?\nA: It must be round neck. Let me think ...OK, I’ll take one of the short sleeve ones. The color’s not so important, really.", questions: [{ q: "When is the man’s appointment?", options: ["Wednesday", "Thursday", "Friday", "Tuesday"], answer: 1 }, { q: "Which is the aunt’s postcard?", options: ["a pretty village right by the sea", "big trees", "a pretty village behind the tall trees", "a pretty village on the hills"], answer: 2 }, { q: "What time will the plane to Milan leave?", options: ["01:00", "07:15", "08:15", "06:15"], answer: 2 }, { q: "Which present has the girl bought her mother?", options: ["earrings", "music", "pen", "notebook"], answer: 2 }, { q: "What time will the pie be ready?", options: ["four fifteen", "five o’clock", "twenty past five", "fifty past four"], answer: 2 }, { q: "What time is the swimming lesson today?", options: ["half past four", "fifteen to five", "fifteen past five", "four thirty"], answer: 1 }, { q: "Which subject does the boy like best?", options: ["information technology", "geography", "sports", "design"], answer: 2 }, { q: "Which T-shirt does the boy decide to buy?", options: ["a short-sleeved T-shirt with round neck", "a V-neck black T-shirt", "a long-sleeved T-shirt", "a sleeveless white T-shirt"], answer: 0 }] } ], },
    { n: 2, title: "Part 2", hint: HINTS[2], recordings: [
      { id: "listening-46-p2", label: "Bài nghe Part 2", audio: "https://cdn.thanhnamnguyen.dev/vstep/audio/listening/listening-23/part1-2.mp3", script: "Conversation 1 (Q.9-12)\nW: I’ve been reading your personal statement, Paul. First, let’s talk about your work experience in South America. What took you there? Was it to gain more fluency in Spanish?\nM: Well, as I’m combining Spanish with Latin American studies, my main idea was to find out more about the way people lived there. My spoken Spanish was already pretty good in fact.\nW: So you weren’t too worried about language barriers?\nM: No. In fact, I ended up teaching English there, although that wasn’t my original choice of work.\nW: How did you find out about all this?\nM: I found an agency that runs all kinds of voluntary projects in South America.\nW: What kind of work?\nM: Well, there were several possibilities.\nW: You mean construction? Engineering work?\nM: Yes, getting involved in building projects was an option. Then there was tourism, taking tourists for walks around the volcanoes which I actually chose to do and then there was work with local farmers.\nW: But you didn’t continue with that project. Why not?\nM: Because I never really knew whether I’d be needed or not. I’d thought it might be difficult physically, but I was certainly fit enough ... no, I wanted to do something that had more of a proper structure to it, I suppose. I get de-motivated otherwise.\nW: What do you think you learned from your experience? It must have been a great opportunity to examine community life.\nM: Yes, but it was difficult at first to be accepted by the locals. It was a very remote village and some of them were reluctant to speak to me although they were always interested in my clothes and how much I’d had to pay for them.\nW: Well, that’s understandable.\nM: Yes, but things soon improved. What struck me was that when people became more comfortable with me and less suspicious, we really connected with each other in a meaningful way.\nW: You made good friends?\nM: Yes, with two of the families in particular.\nW: Good. What about management. Did you have a project manager?\nM: Yes and he gave me lots of advice and guidance.\nW: And was he good at managing too?\nM: That wasn’t his strong point! I think he was often more interested in the academic side of things than filing reports. He was a bit of a dreamer.\nW: And did you have a contract?\nM: I had to stay for a minimum of three months. My parents were surprised when I asked to stay longer - six months in the end. I was so happy there.\nW: And did anything on the administration side of things surprise you? What was the food and lodging like?\nM: Simple ... but there was plenty to eat and I only paid seven dollars a day for that which was amazing really. And they gave me all the equipment I needed ... even a laptop.\nW: You didn’t expect that then?\nM: No\nW: Well, I’ll look forward to hearing more.\nConversation 2 (Q.13-16)\nW: Hi Jun. As you know, I’ve asked you here today to discuss the future of our Self-Access Centre. We have to decide what we want to do about this very important resource for our English language students. So, can you tell me what the students think about this?\nM: Well, from the students’ point of view, we would like to keep it. The majority of students say they enjoy using it because it provides a variation on the classroom routine and they see it as a pretty major component of their course, but we would like to see some improvements to the equipment, particularly the computers; there aren’t enough for one each at the moment and we always have to share.\nW: Well yes, the teachers agree that it is a very valuable resource but one thing we have noticed is that a lot of the students are using it to check their personal emails. We don’t want to stop you students using it, but we think the computers should be used as a learning resource, not for emails. Some of us also think that we could benefit a lot more by relocating the Self-Access Centre to the main University library building. How do you think the students would feel about that, Jun?\nM: Well, the library is big enough to incorporate the Self-Access Centre, but it wouldn’t be like a class activity anymore. Our main worry would not be being able to go to a teacher for advice. I’m sure there would be plenty of things to do but we really need teachers to help us choose the best activities.\nW: Well, there would still be a teacher present and he or she would guide the activities of the students. We wouldn’t just leave him to get on with it.\nM: Yes, but I think the students would be much happier keeping the existing set-up; they really like going to the Self-Access Centre with their teacher and staying together as a group to do activities. If we could just improve the resources and facilities, I think it would be fine. Is the cost going to be a problem?\nW: It’s not so much the expense that I’m worried about, and we’ve certainly got room to do it, but it’s the problem of timetabling a teacher to be in there outside class hours. If we’re going to spend a lot of money on equipment and resources, we really need to make sure that everything is looked after properly. Anyway, let’s make some notes to see just what needs doing to improve the Centre.\nConversation 3 (Q.17-20)\nW: For the second in our series about locally-run businesses, we meet Simon Winridge, co-founder of the hugely-successful Winridge Forest Railway Park. Welcome, Simon. Now, perhaps you can begin by telling us a little bit about how it all started.\nM: Well, during the 1970s, my wife, Liz and I had just acquired 80 acres of sheep-farming land, and we decided to settle down and have children. Pretty soon we had a daughter, Sarah, and a son, Duncan. The place was wonderful for the kids: they particularly loved trains and gradually built up an enormous network of miniature railway track. I began to develop larger-scale models of locomotives but we didn’t think anything more of it until I went on a trip to a theme park near Birmingham and decided we could do a much better job! So we set up a small one ourselves based on the miniature railway and we opened to the public for just a month that year. 1984 - in July - our driest month because our children said they didn’t want our guests to have a miserable, wet visit. I dealt with Park business and Liz carried on with the farm work. It soon became clear that we were onto a winner. We began to extend the railway track and lay it among more interesting landscape by planting trees, which in turn attracted more wildlife, and by making cuttings through the rock. Nowadays, we’re open all year round and we’re pleased to say that Winridge is one of the most popular visitor attractions in the area with 50,000 visitors a year - a million and a half people have been through our doors since we opened. All these visitors mean we have had to expand our operation and it’s now a truly family concern I’m near to retirement age so I only concern myself with looking after the mechanical side of things - keeping the trains going. Liz now devotes all her energies to recruiting and supporting the large squadron of workers, which keep the place running smoothly. We're really pleased that after some years away teaching, Sarah has now returned to the park and makes sure the visitors are kept fed and watered, which keeps her pretty busy as you can imagine. Our son Duncan has been a stalwart of the park for the last 10 years, taking over from me and the area of construction and I'll say a little bit more about that in the moment. And his new wife Judith has also joined the team in charge of retail. That’s becoming a tremendous growth area for us a lot of people want to buy souvenirs.", questions: [{ q: "What was Paul's main purpose in going to South America?", options: ["To develop his spoken Spanish through daily use", "To gain a better understanding of local life", "To obtain practical experience in teaching", "To explore possible careers in the region"], answer: 1 }, { q: "Which voluntary activity did Paul eventually choose?", options: ["Taking visitors on local tours", "Helping with construction projects", "Working alongside local farmers", "Teaching English to village residents"], answer: 0 }, { q: "What weakness did Paul notice in his project manager?", options: ["He gave too little practical guidance", "He struggled to organize the project's paperwork", "He was more interested in theory than administration", "He spent too much time supervising physical work"], answer: 2 }, { q: "What did Paul find particularly unexpected about his living arrangements?", options: ["The basic conditions were combined with very low costs", "The food was much better than he had expected", "He was provided with more equipment than he needed", "The accommodation was more comfortable than the village"], answer: 0 }, { q: "Why do students regard the Self-Access Centre as important?", options: ["It allows them to study without teacher supervision", "It provides an alternative to their usual classroom routine", "It gives them regular access to personal online services", "It contains equipment that is unavailable elsewhere"], answer: 1 }, { q: "What change has been proposed by some members of staff?", options: ["Providing each student with a computer", "Limiting access to students on particular courses", "Replacing independent study with classroom activities", "Moving the centre to another university facility"], answer: 3 }, { q: "What is Jun most concerned about if the centre is relocated?", options: ["Students may have less access to guidance", "The new location may be too small for everyone", "Students may have fewer learning activities available", "Teachers may no longer be able to use the equipment"], answer: 0 }, { q: "What practical difficulty does the Director of Studies identify?", options: ["Finding enough money for new equipment", "Providing staff coverage beyond normal class time", "Finding sufficient space within the university library", "Preventing students from using computers for emails"], answer: 1 }, { q: "What prompted Simon to start his own theme park?", options: ["He wanted to develop the family farm commercially", "He believed an existing park could be improved", "His children wanted to build larger railway models", "He wanted to make better use of the local wildlife"], answer: 1 }, { q: "Why did the family choose July for the park's first opening?", options: ["The weather was usually suitable for visitors", "The timing fitted around their farming work", "The children were free from school commitments", "They needed the summer to complete the railway"], answer: 0 }, { q: "What does Simon's visitor figure suggest about the park's long-term popularity?", options: ["It has attracted around 50,000 visitors since opening", "It has received roughly 500,000 visitors altogether", "It has welcomed about one and a half million visitors", "It now attracts around one million visitors every year"], answer: 2 }, { q: "Which member of the family has taken on responsibility for catering for visitors?", options: ["Simon, after reducing his mechanical duties", "Liz, as part of managing the park's workforce", "Judith, alongside her work in retail", "Sarah, after returning from another career"], answer: 3 }] } ], },
    { n: 3, title: "Part 3", hint: HINTS[3], recordings: [
      { id: "listening-46-p3", label: "Bài nghe Part 3", audio: "https://cdn.thanhnamnguyen.dev/vstep/audio/listening/listening-12/part1-3.mp3", script: "Conversation 1 (Q.21-25)\nW: Hi, there. I was looking for information about becoming a political science major.\nM: Sure. We have some brochures right here.\nW: Thanks, but could I ask you a few questions?\nM: No problem. Fire away.\nW: Are there many requirements for Political Science?\nM: Uh, not really ... Just you must take Political Science 1 and 2, a general history class, and a writing seminar.\nW: I thought you had to take economics, too.\nM: Not for the general Political Science program. But there are a couple of specialized programs that have additional requirements.\nW: Oh, really? What are they?\nM: Well, there is the International Relations program. It is more interdisciplinary, so it requires economics and a second history credit; the two history credits have to be in different regions. There is also the honors Political Science program. To get into that, you need to take the same economics class as the International Relations program, and a special Political Science seminar. And you need to maintain over a \"B\" average in all those required courses.\nW: Wow, that sounds difficult.\nM: Yeah, not many people are qualified for the honors program. That's why it's considered more prestigious, I guess.\nW: Is that all?\nM: No. You also have to complete this form, listing all the Political Science and related credits you have already taken or plan to take, and get the department chair to sign off on it.\nW: Uggh. This is really a lot of work.\nM: Yeah, but everyone has to do it. It's not different from any other majors; the department wants to know that you've thought about your major carefully and thoroughly, and that all the students are being realistic in their expectations.\nConversation 2 (Q.26-30)\nM: Hey, Clara. Got a minute?\nW: Oh, hi, Will. Sure, I've got plenty of time. What's the matter?\nM: Did you see the poster saying that our debate club meeting tonight had been moved?\nW: Oh yes, you didn't get the email?\nM: My computer hasn't been working these few days, so I can't get access to my mailbox. Anyway, why has it been moved?\nW: That whole wing of the Student Union building is getting repainted today, so it's off-limits until the paint dries, vented properly and the workers clean everything up.\nM: It's about time. The club offices in the student building have been looking rundown for quite a while now. A new paint-job would do them a world of good.\nW: And the rooms are going to be repainted in a lighter color, too. That old paint was too dark and depressing.\nM: A lighter color would help everything look bigger, too. Our debate club could use that.\nW: Yeah, but we need more than just light paint. We've grown too big for that little room; we really need to move into a bigger place.\nM: Any chance of that happening?\nW: Not that I know of. Except for tonight, that is, just for this once, we'll be meeting downstairs in Turner Auditorium.\nM: That place is huge, way too big for us.\nW: I know, but it was the only place available tonight. And it was either there or else cancel the meeting altogether.\nM: I guess it's better than canceling. Although, to be honest, I could use another week to prepare for my speech, I've been really busy with my classes lately.\nConversation 3 (Q.31-35)\nScience fiction is very popular these days - in books, in movies, and on TV. Unfortunately, popular science fiction is often a lot more \"fiction\" and not so much \"science.\" One of the most common problems is science fiction’s fascination with faster-than-light travel. We know that is impossible, as it violates Einstein’s basic theory of space and time, but on Star Trek and other science fiction shows, spaceships jump from star to star and galaxy to galaxy like you or I might want to drive to another city. In truth, the closest star to Earth, Proxima Centauri, is over three light years away. That means traveling at the speed of light, the fastest speed anyone theoretically could travel, it would take three years to make it to our nearest neighbor. Other stars and galaxies are routinely thousands and millions of light years away, making intergalactic travel an impossibility. Even if we grant that such space travel somehow was possible, there is no shortage of other errors in popular science fiction. In Star Wars and other films, spaceships swoop across the screen, with their ... uh ... their engines emitting a great roar. However, since space is a void, sound waves cannot travel. There is no sound in space; it is utterly silent. Gravity is another mystery in these films. Gravity depends mostly on mass. Spaceships are tiny compared to the mass of earth. In space there should be practically no gravity. And yet people in science fiction routinely walk around on their spaceships in space as comfortably as they would on earth. That said, there have been a few, scarce films that bothered to portray the science of space flight somewhat realistically. In 2001: A Space Odyssey, the ship must rotate to create artificial gravity. Outside the spaceship, there is total silence. And the voyage from Earth to Jupiter takes many months. But such films are the exception, not the rule. While science fiction may be enjoyable, you should look elsewhere to learn about science.\nNguồn: https://vstepowl.com/listening/de-thi/?exam=listening-46", questions: [{ q: "What is the woman mainly trying to find out?", options: ["Whether her existing credits can be transferred.", "Whether she meets the honors program requirements.", "What she needs to study for a Political Science major.", "How difficult the Political Science courses are."], answer: 2 }, { q: "What misunderstanding does the woman have about the general program?", options: ["She thinks a history course is optional.", "She thinks an economics course is required.", "She thinks a writing seminar is unnecessary.", "She thinks Political Science 1 is not required."], answer: 1 }, { q: "What makes the history requirement for International Relations more demanding?", options: ["Students must study two different historical regions.", "Students must replace history with an economics course.", "Students must take history at a more advanced level.", "Students must complete two additional history seminars."], answer: 0 }, { q: "Why does the man associate the honors program with greater prestige?", options: ["It offers more specialized courses than other programs.", "It attracts students from several different departments.", "Its requirements are difficult for many students to satisfy.", "Its students do not need to complete the usual requirements."], answer: 2 }, { q: "What is the main purpose of the department's detailed registration process?", options: ["To make Political Science harder to enter than other majors.", "To compare students' academic records with other departments.", "To determine which students qualify for the honors program.", "To ensure students have planned their studies realistically."], answer: 3 }, { q: "Why will the debate club meet in Turner Auditorium tonight?", options: ["Its usual room is unavailable because of repainting.", "The club expects an unusually large audience.", "The club has permanently moved to a larger venue.", "Its usual room is being used by another organization."], answer: 0 }, { q: "Why did the man miss the email about the meeting change?", options: ["He had not checked his email recently.", "His computer was not functioning properly.", "He had been away from the university.", "The club had sent the message to the wrong address."], answer: 1 }, { q: "What is the repainting expected to improve besides the appearance of the building?", options: ["The amount of space available for club activities.", "The number of organizations using the building.", "The condition of the club's office equipment.", "The atmosphere of the rooms used by students."], answer: 3 }, { q: "What problem will remain after the repainting is completed?", options: ["The club will still need a larger meeting room.", "The building will still require further repairs.", "The club will still lack enough members.", "The rooms will still have poor lighting."], answer: 0 }, { q: "What does the man's final comment suggest about his speech?", options: ["He has decided not to give the speech tonight.", "He feels he needs more time to prepare it.", "He wants to change the subject of his speech.", "He is confident that the speech is already finished."], answer: 1 }, { q: "What is the main purpose of the professor's talk?", options: ["To explain why science fiction has become popular.", "To compare different approaches to making science fiction.", "To identify scientific inaccuracies in popular science fiction.", "To introduce several successful science fiction films."], answer: 2 }, { q: "Why does the professor use Proxima Centauri as an example?", options: ["To show how quickly modern spaceships can travel.", "To explain why galaxies are difficult to observe.", "To demonstrate how far even the nearest star is.", "To prove that light travels differently between stars."], answer: 2 }, { q: "Why does the professor criticize the sound effects in space films?", options: ["Spacecraft engines would actually be much louder.", "Sound cannot travel through the vacuum of space.", "Astronauts would hear only sounds inside their ships.", "Modern spacecraft use completely different engines."], answer: 1 }, { q: "What does 2001: A Space Odyssey demonstrate that most science fiction films do not?", options: ["It shows that faster-than-light travel is achievable.", "It focuses mainly on the dangers of artificial gravity.", "It avoids showing long journeys between distant planets.", "It presents space travel using more realistic science."], answer: 3 }, { q: "What conclusion does the professor draw about using science fiction to learn science?", options: ["Only older science fiction can provide reliable information.", "Popular films are useful if viewers understand their limitations.", "Science fiction is generally entertaining but unreliable as a science source.", "Realistic science fiction can replace more traditional science materials."], answer: 2 }] } ], },
  ] },
  { id: "listening-47", title: "Đề 47", subtitle: "35 câu · 40 phút", durationMin: 40, parts: [
    { n: 1, title: "Part 1", hint: HINTS[1], recordings: [
      { id: "listening-47-p1", label: "Bài nghe Part 1", audio: "https://cdn.thanhnamnguyen.dev/vstep/audio/listening/listening-16/part1-1.mp3", script: "Q.1: Where would you probably hear this announcement?\nGood morning, everyone. Please remember, we have a meeting today in the large meeting hall on the second floor at 10 o'clock this morning. All staff must attend. We will talk about the move to our new office building. We will move next Monday. So, you need to know what to do, and where you need to be on Monday. So please make sure that you are on time for today's meeting.\nQ.2: Where would someone hear this message?\nThank you for calling the law offices of Jones and Leung. If you are looking for a lawyer to help you with a problem, please press 1. If you are a lawyer from another company, please press 2. If you are a journalist, please press 3 to speak with our office manager. For all other questions, press 0 and someone will be with you soon. To hear this message again, press 9.\nQ.3: How long are the classes?\nRemember. Everyone needs to attend the Sales Training this Wednesday. The first class will start at 9 o'clock. At 10:30 we'll have a short coffee break. The second class will start at 10:45. We'll have lunch from 12:15. The third class will start at 1:30 pm, then a short break. The last class will start at 3:15 and finish at 4:45. That's the day after tomorrow. Don't forget.\nQ.4: What should Jen do tomorrow?\nHi, everyone. Meet Jen, she'll be joining our team starting today. Jen worked in the head office for five years, but from today, she'll be working with us. Please note that Jens email address is her home address because she doesn't have her new office email address yet. When Jen gets her new office email address tomorrow, she'll give her new address to everyone.\nQ.5: What is the purpose of this announcement?\nMay I have your attention? Because of the weather, flight number 446 is going to be a bit late leaving. It's just too dangerous to take off in this high wind. As soon as this thunderstorm passes, we will take off. We apologize for the inconvenience.\nQ.6: What is the main point of this announcement?\nThank you for coming to see the Pacific Art Museum's exhibition of eighteenth century landscape paintings. The museum will be closing in fifteen minutes. Please begin moving to the museum exits.\nQ.7: Who is Gary Reynolds?\nHi, this is Gary Reynolds, from Skyline Airlines. You recently bought a ticket for February 16th on flight number 681 from Los Angeles to San Francisco. Unfortunately, there was an error on our website. That flight actually takes off at 9:40 am, not 10:40 as it said on the website. If that is a problem, please call me at the customer service line, 334-445-9284, and we will reschedule you to another flight. I'm sorry for the confusion.\nQ.8: What does the woman recommend the listeners to do?\nLadies and Gentlemen. I'm very sorry we woke you up in the middle of the night. There was a small fire in the hotel's kitchen, but everything is okay now. The Fire Department has put out the fire. You can return to your rooms. It's completely safe. We're very sorry for the trouble.", questions: [{ q: "Where would you probably hear this announcement?", options: ["In a moving van", "In a school", "In an office building", "In an office supply shop"], answer: 2 }, { q: "Where would someone hear this message?", options: ["Calling a newspaper company", "Calling a journalist", "Calling a telephone company", "Calling a law firm"], answer: 3 }, { q: "How long are the classes?", options: ["45 minutes", "An hour", "An hour and a half", "Two hours"], answer: 2 }, { q: "What should Jen do tomorrow?", options: ["Turn her cell phone back on", "Check her email, even if it is at home", "Make sure she gets an office address", "Give people her new contact information"], answer: 3 }, { q: "What is the purpose of this announcement?", options: ["To discuss the news", "To give information", "To ask for help", "To demand a report"], answer: 1 }, { q: "What is the main point of this announcement?", options: ["To welcome visitors", "To ask people to leave soon", "To tell people about the exhibition", "To ask people to come"], answer: 1 }, { q: "Who is Gary Reynolds?", options: ["A security officer", "An airline pilot", "A flight attendant", "An airline employee"], answer: 3 }, { q: "What does the woman recommend the listeners to do?", options: ["Go to the website", "Go back to their rooms", "Talk to the hotel manager", "Wait for more information"], answer: 1 }] } ], },
    { n: 2, title: "Part 2", hint: HINTS[2], recordings: [
      { id: "listening-47-p2", label: "Bài nghe Part 2", audio: "https://cdn.thanhnamnguyen.dev/vstep/audio/listening/listening-17/part1-2.mp3", script: "Conversation 1 (Q.9-12)\nM: All right. Saturday's the big day. Are you ready? Yes, Susan?\nW: Tests make me nervous. What can I do?\nM: Good question. It's natural to be a little nervous before a test. The important thing is: don't panic. You've studied hard for this test. You can pass it. Be confident! Relax! Now, you're more likely to be relaxed if you are well prepared. Here are some tips. First, before you leave home, check to make sure you have everything you need. You should have your admission ticket. This was mailed to you last week. You should have two number-two pencils and a good eraser. You should have identification your student ID card, a driver's license, or a passport. If you're taking the math portion of the test, you should have a calculator. Second, know what you can't bring to the test. You cannot bring a watch with a loud alarm. You cannot bring any food or drink. You cannot bring extra paper to write on. You cannot bring any books, notes, or dictionaries. You cannot bring compasses, rulers, protractors, or other aids - except for the calculator. You cannot bring colored pens, pencils, or highlighters. You cannot bring cell phones or pagers. You cannot bring any portable tape recorders, walkmans, or headphones. Questions?\nW: Um...what if I uh, have to go to the bathroom during the test?\nM: You can't. So go before! Don't worry, there will be breaks after each section of the test. You'll be able to go then.\nConversation 2 (Q.13-16)\nW: Hi there. On last week's programme, we interviewed the man behind the idea of the International camps so I thought that this week you'd be interested to hear more about one of the camps which will be held later this year over to you Michael.\nM: Thank you. Yes, the Camp is open to everyone between the ages of 18 to 23. You don't have to be a student. You don't even have to be employed but you must be able to speak one foreign language in addition to your mother tongue.\nW: OK. And what about accommodation?\nM: Well, the International Camp organisers supply tents which sleep up to four people. But you are unlikely to know the people who you'll be sharing a tent with. The nationalities are mixed so you'll be sharing with people who may not even speak your language!\nW: Sounds interesting. Who does the cooking at the Camp?\nM: Everybody is expected to help with the running of the Camp. That means helping to prepare food, keeping the camp site clean and tidy, and so on. The Camp organisers are looking for people who can get along with others whatever happens.\nW: And is there anything you need to take?\nM: Well as I've said, tents are provided but you'll need to bring your own pillow, knife, fork and spoon. If you get chosen, you're also asked to bring along photographs, postcards, anything that shows some of the traditions and customs of your own country. Everything goes into an exhibition at the start of the Camp together with a huge map of the world showing the different countries people come from.\nW: And is there any entertainment?\nM: Yes, there is. Everyone helps to provide the Camp entertainment. You are expected to sing, dance or play something musical. It doesn't matter how good or bad you are. There is a space on the form to write down what you can do.\nW: Sounds great fun. And what does it all cost?\nM: Well, you have to find your own way to the Camp so it's up to you whether you fly, cycle, walk, hitch-hike or whatever. The charge for a week's Camp is 300 dollars. But you'll have to change that into your own currency to get a better idea of the cost. You have to pay the full cost before you arrive. But you can pay in any currency you want or you can use a credit card if you have one. Right. Now for the phone number to ring.\nConversation 3 (Q.17-20)\nW: In today's programme. David Green has come along to tell us all about Waterside Shopping Centre near Northport. Good morning, David.\nM: Good morning. Well, I visited Waterside last week and I think it has something for everyone and I would recommend it for a day out. It's taken three years to build and finally opened three weeks ago, two months later than planned. Firstly, getting there; there are organized coach trips from most towns in the area but they leave early and come home very late, so I drove. There are 12,000 free parking spaces, so parking is no problem. You can also get there by train, but the station is 15 minutes from Waterside by bus and the buses are really crowded so you sometimes have a long wait.\nW: And what about opening times?\nM: Well, one thing to remember is that the shops don't open till 10.00 in the morning except on Saturday when they open at 9.00. So don't get there too early on a weekday. They close at 8 o'clock every day except Friday when they're open until 9 pm.\nW: Can you tell us some more about the facilities at the shopping centre?\nM: Yes, it's arranged on three levels. You'll find all your favourites here. In fact, if you want to buy a pair of shoes there are 15 different shops to choose from on levels one and two. When you run out of money there are seven different banks but collect your money before you get to the third level as there aren't any banks up there. On that level, however, there are several restaurants as well as a cinema with seven screens. And don't get lost like I did, go to the information desk on the first level and get a map.\nW: What else can you do at Waterside?\nM: Before you go back to your car or the bus and in fact it might be better to do this before you go shopping and have too much to carry go and see the lake. Take a walk or have a go at fishing, sailing or wind surfing if you have time. Or you can rest your tired feet and watch the birds and ducks, but you are asked not to feed them.\nW: Was there anything you didn't like about the shopping centre?\nM: Oh. Well, although I had a good day, I would complain about one thing but not the usual thing the service in the shops was good and I had an excellent lunch in a cafe. No, the silly thing was that everywhere was quite clean but people were dropping their sweet papers and empty drink cans on the ground because there wasn't anywhere else to throw them. Apart from that I would recommend it.\nW: And so that's all for today's programme.", questions: [{ q: "Why must students bring identification to the test?", options: ["To confirm their identity before taking the test.", "To register for the test on Saturday.", "To receive their test results afterward.", "To borrow equipment during the test."], answer: 0 }, { q: "Why does the professor emphasize being well prepared?", options: ["It helps students finish the test more quickly.", "It helps students remain calm during the test.", "It guarantees students will pass the test.", "It prevents students from making careless mistakes."], answer: 1 }, { q: "What is the professor mainly explaining?", options: ["How the test will be scored.", "What topics the test will cover.", "Which items students may bring.", "How long each test section will last."], answer: 2 }, { q: "What can be inferred from the professor's opening remark?", options: ["The test is scheduled for the coming Saturday.", "The students have classes every Saturday.", "The test is the final event of the semester.", "The professor expects a particularly difficult test."], answer: 0 }, { q: "Which is a requirement for joining the International Camp?", options: ["Applicants must be university students.", "Applicants must have a full-time job.", "Applicants must speak another language.", "Applicants must have previous camp experience."], answer: 2 }, { q: "What should participants expect when sharing a tent?", options: ["They may share with people from different countries.", "They will share with three people they already know.", "They will stay with people who speak their language.", "They will choose their own tent before arriving."], answer: 0 }, { q: "Which item do participants not need to bring?", options: ["A pillow for sleeping.", "A tent for accommodation.", "A knife for preparing food.", "A spoon for eating meals."], answer: 1 }, { q: "What is required when paying the camp fee?", options: ["The full amount must be paid in advance.", "The fee must be paid in US dollars.", "Payment must be made after arriving.", "Participants must pay by credit card."], answer: 0 }, { q: "Why did the speaker decide to drive to Waterside?", options: ["The train station is too far away.", "The coaches are usually overcrowded.", "There is plenty of free parking available.", "The buses stop running early."], answer: 2 }, { q: "What is different about Waterside's Friday opening hours?", options: ["The shops open earlier than usual.", "The shops close later than usual.", "The shops close earlier than usual.", "The shops remain open all night."], answer: 1 }, { q: "What are visitors asked not to do at the lake?", options: ["Go fishing during their visit.", "Walk around the lake.", "Feed the birds and ducks.", "Try water sports on the lake."], answer: 2 }, { q: "What problem does the speaker mention about the centre?", options: ["The shops provide poor customer service.", "There are not enough places to eat.", "The centre is difficult to reach by car.", "There are not enough bins for rubbish."], answer: 3 }] } ], },
    { n: 3, title: "Part 3", hint: HINTS[3], recordings: [
      { id: "listening-47-p3", label: "Bài nghe Part 3", audio: "https://cdn.thanhnamnguyen.dev/vstep/audio/listening/listening-13/part1-3.mp3", script: "Conversation 1 (Q.21-25)\nW: Can you believe Professor Kensington postponed the due date for the term paper this morning? It's unbelievable!\nM: Yeah, it was crazy! I've been spending days and nights in the computer lab writing up that paper. I only did that because he kept on emphasizing that he won't take any paper that's not in his office by noon today.\nW: I heard that, too. Jessica and I stayed up half the night trying to finish it. I think it was three o'clock in the morning when we finally had the third draft. I barely had any sleep.\nM: You had Jessica to help you? At least you had someone to proofread your paper and help you with the research. It was a nightmare for me. I didn't even have time to proofread my paper.\nW: Well, I'm really upset that Professor Kensington was so inconsiderate. Don't you agree?\nM: I guess it was a hasty change, but... I think he did it for us students.\nW: You really didn't get enough sleep, did you? You're not thinking straight. I can't possibly see how I can understand his hasty decision that way.\nM: Well, as much as I'm unhappy with his last-minute decision, I think he did it so that we could have one more chance to look over our work before turning it in. Besides, an extension of two days isn't going to change anything drastic in our papers.\nW: I suppose. Still, I would have had more time to study for the calculus exam, which was today, if I hadn't had to spend so much time and energy on that paper.\nM: Oh well, at least he didn't tell us to hand it in earlier.\nW: That's right... anyway, I'm not going to spend another two days on the assignment. I'm handing it in after the next class.\nConversation 2 (Q.26-30)\nW: Professor Atkins, could I get some help with my chemistry lab?\nP: Certainly, Julie. What's the problem? Are you having trouble understanding some of the experiments?\nW: Oh, no, I understand the experiment ...perhaps I only think that I understand it.\nP: What do you mean? Do you or don't you?\nW: Well, I tried the latest experiment by myself, based on what I understood from your lectures and lab session ... but I seem to come up with really different results from what the textbook indicates I should be getting.\nP: That certainly is a possibility. Remember, the textbook tends to give you an ideal explanation of the experiments. But in real life, any number of factors can cause you to get results that might not be the ideal or preferred outcome.\nW: Oh, that's good... so any result is acceptable?\nP: No, of course there is a range for this particular experiment, I'd expect your answer to be within ... let's see now... perhaps 4 or 5% off the textbook.\nW: Really? My answer was nearly 10% off. Wouldn't that be alright?\nP: I'm sorry, but that would be a problem. If your answer were that far from the proper answer, and say that even if you could explain the difference, I would have to lower your grade significantly.\nW: I see. Alright. I guess I'm going to have to redo it. I want to do well in your class and can't afford to get a bad grade.\nP: Very good. But you'll have to hurry, the lab is due Friday, and I won't be giving any extensions.\nW: Oh, I was hoping...\nP: Yes, it's nothing. Well, could you please sign a permission slip for me to use the lab after hours? I only have time during late evenings this weekend.\nP: Sure, I'll do that for you right now. Here you go... and a tip... before you start the experiment, wipe the test tubes with alcohol... there might be unwanted residue inside that might be affecting the result.\nConversation 3 (Q.31-35)\nWe'll be looking into the largest state in America, Alaska. If you look at the location of Alaska on the map, you can see that it is bordered by Canada on the east, the Arctic Ocean on the north, the Bering Strait and Bering Sea to the east, and the Gulf of Alaska ... wait a minute ... sorry about that... to the west and the Gulf of Alaska to the south. And as you can see on the map, Alaska has a greater land area than California and Texas combined. Now, although there are many cities in Alaska, the population is so low that an average number of students in a middle school classroom is only about 10. You can imagine many desolate small towns scattered around Alaska. So, it's natural that Alaskans rely heavily on airplanes for transportation, since many parts of Alaska are accessible only via air. Well, of course, there is a railway operating between Fairbanks, a relatively big city in central Alaska, and Seward, a city on the southern coast. It is much more popular than the only major highway in Alaska, the Alaska Highway, which is open throughout the year. Not that there's much traffic. One does not need to venture far to understand the reason for its sparse population. Even though cold climate and other factors make most of Alaska a less-than-desirable location for farming, agriculture is conducted in a few areas between Fairbanks and the southern coast. Most of the food Alaskans need, however, must be imported from outside the state. Also, Alaska is subject to strong earthquakes and occasional volcanic activity. Your textbook describes the explosion of the Alaskan volcano Mount Katmai in the early 20th century as one of the most famous and violent volcanic eruptions in history. I strongly suggest you read up on that chapter, as we'll be touching on some of that the next time. Anyway, where was I? Oh yes, earthquakes ... these occasional earthquakes generate seismic sea waves, called tsunamis. As you may have heard, these waves can reach far inland and destroy communities along the shore. It wasn't much different from the terrible tsunami of 2004.\nNguồn: https://vstepowl.com/listening/de-thi/?exam=listening-47", questions: [{ q: "What does the woman imply about her work on the paper?", options: ["She completed several drafts with Jessica's help.", "She finished it quickly without much revision.", "She stopped working on it before completing a draft.", "She wrote it alone without anyone reviewing it."], answer: 0 }, { q: "What was the main difference between the students' experiences?", options: ["The woman worked at home while the man used the lab.", "The woman studied for calculus while the man wrote his paper.", "The woman had help with her paper while the man worked alone.", "The woman submitted her paper while the man was still writing."], answer: 2 }, { q: "What does the man's response suggest about his opinion of the extension?", options: ["He thinks the professor should have extended it even longer.", "He dislikes the timing but understands why the professor did it.", "He believes the professor changed it without considering students.", "He agrees completely with the professor's decision and timing."], answer: 1 }, { q: "Why does the man think two extra days will make little difference?", options: ["Most students have already finished their papers.", "The professor will probably accept unfinished papers.", "The original deadline was not strictly enforced anyway.", "The extra time is unlikely to change the completed work much."], answer: 3 }, { q: "What does the woman decide to do with the extra time?", options: ["Submit the paper after the next class.", "Use both extra days to revise the paper.", "Spend the extra time preparing for calculus.", "Ask the professor for another extension."], answer: 0 }, { q: "What does Professor Atkins suggest about differences from textbook results?", options: ["They usually mean the student misunderstood the experiment.", "They can occur because real conditions are not ideal.", "They show that textbook explanations are generally unreliable.", "They are normally caused by problems with the equipment."], answer: 1 }, { q: "Why is Julie's result considered unacceptable?", options: ["It is outside the experiment's expected error range.", "It is different from every result in the textbook.", "It was obtained without the professor's permission.", "It is much closer to the expected result than required."], answer: 0 }, { q: "What does Professor Atkins imply will happen if Julie cannot correct the problem?", options: ["She will have to repeat the entire chemistry course.", "She will receive a lower grade for the laboratory work.", "She will be allowed to submit the report after Friday.", "She will receive full credit if she explains the difference."], answer: 1 }, { q: "What constraint does Julie face when redoing the experiment?", options: ["She cannot use the laboratory outside normal hours.", "She must complete the experiment before the next class.", "She has to finish it by Friday without an extension.", "She must ask another student to supervise her work."], answer: 2 }, { q: "What does the professor suggest may have affected Julie's results?", options: ["A misunderstanding of the textbook explanation.", "A measurement error during the experiment.", "A problem with the laboratory equipment.", "Residue left inside the test tubes."], answer: 3 }, { q: "After correcting himself, which location does the professor identify as being west of Alaska?", options: ["The Gulf of Alaska.", "The Arctic Ocean.", "The Bering Strait and Bering Sea.", "The Canadian border."], answer: 2 }, { q: "What do the professor's comments about Alaska's size and classrooms mainly illustrate?", options: ["Its population is small compared with its huge territory.", "Its schools are spread evenly across the entire state.", "Its largest cities contain most of the state's farmland.", "Its population has grown rapidly despite its harsh climate."], answer: 0 }, { q: "Why does the professor mention that there is not much traffic on the Alaska Highway?", options: ["To show that the highway is difficult to use year-round.", "To emphasize how few people live across much of Alaska.", "To compare the highway with Alaska's railway system.", "To explain why most Alaskans prefer traveling by train."], answer: 1 }, { q: "Why does the professor tell students to read the section on Mount Katmai?", options: ["It explains why farming is difficult in Alaska.", "It describes the main transportation routes in Alaska.", "It provides background for a topic they will discuss next.", "It contains information about Alaska's largest cities."], answer: 2 }, { q: "What broader point does the professor make about Alaska's natural environment?", options: ["Its natural hazards can seriously affect people and communities.", "Its volcanic activity is more important than its earthquakes.", "Its coastal areas are largely protected from major disasters.", "Its harsh climate is the only major environmental challenge."], answer: 0 }] } ], },
  ] },
  { id: "listening-48", title: "Đề 48", subtitle: "35 câu · 40 phút", durationMin: 40, parts: [
    { n: 1, title: "Part 1", hint: HINTS[1], recordings: [
      { id: "listening-48-p1", label: "Bài nghe Part 1", audio: "https://cdn.thanhnamnguyen.dev/vstep/audio/listening/listening-23/part1-1.mp3", script: "Question 1.\nGreat Midland Railway would like to apologize to passengers as we will not be providing the advertised buffet service with tea, coffee cold drinks and full English and continental breakfasts on this journey. This is due to fire in the locomotive shed before departure. A trolley service is available, however which will be visiting all coaches with a selection of cold drinks and sandwiches. Passengers are requested to remain in their seats for this service.\nQuestion 2.\nWell, I was afraid you’d have to wait till Thursday but I just talked to the engineer and er today’s Tuesday, isn’t it he said you could pick it up tomorrow Is that all right for you?\nQuestion 3.\nMotorists travelling to Bury are notified of a serious fire in the town. The traffic isn’t moving at all and there are hold ups in all directions. Avoid Bury if you can. In Birmingham there’s already heavy traffic around Edgbaston as the crowds arrive for the cricket final. There are a number of minor roads closed around the cricket ground so if you’ve got a ticket for the final make sure you give yourself plenty of time to get there On the M11 to Cambridge there’s been...\nQuestion 4.\nIt’s 7.30 and now we have a choice of our viewers here in Wales. On HTV we have Bill Barnard and Ian Fall in The Sport in Question. On TSW we have a documentary on the 400th anniversary of Sir Francis Drake’s death which examines Drake’s last voyage to the Caribbean and on Channel 4 Wales there’s an adaptation of Johns McShene’s novel about modern university life. A Place in History.\nQuestion 5.\nI’ve got instructions for getting to Dad’s new house here, Ken. Turn off at junction 28 and take the first turning signposted to the City centre and Barnstable. After that, drive for about 200 yards and there’s another left turn. There’s no signpost but he says it leads to Matlock village and it’s called Gate Lane. The new house is 150 yards along on the right. It’s an old brick building with a lovely…\nQuestion 6.\nideal for a weekend break. We have indoor heated swimming pools Jacuzzis and saunas three gymnasia with qualified fitness instructors all freely available to guests. There are three top class restaurants to cater for every taste. And even a crèche so the busy mum and dad are free to enjoy the facilities. Double and single rooms can be booked only through.\nQuestion 7.\n...and all passengers should disembark while the plane is being refuelled. This should take about 45 minutes. Passengers to London should follow the signs to the luggage collection points and the exits. Passengers continuing their journeys to destinations in Europe should proceed to terminal B. There is a bus to take you there. Passengers continuing their flight to the USA should wait in the departure lounge. We will call you as soon as it is safe for you to reboard the plane. On behalf of Air Midland, I would like to thank you for choosing.\nQuestion 8.\nA woman whose life was saved by an emergency operation while on a flight from Cape Town to Jakarta will take another flight to Jakarta tomorrow this time on her honeymoon. Georgina Curry survived thanks to quick thinking from two doctors on board the plane who performed an emergency appendix operation at 30,000 feet. But today only love is in the air Miss Curry marries her fiancé David Hume.", questions: [{ q: "What can you get on the train?", options: ["full English breakfast", "full continental breakfast", "tea and coffee", "sandwiches"], answer: 3 }, { q: "When will the television be ready for collection?", options: ["on Tuesday", "on Wednesday", "on Thursday", "on Friday"], answer: 1 }, { q: "What should people going to Birmingham do?", options: ["cancel the trip", "leave early", "use minor roads", "use Bury road"], answer: 1 }, { q: "Which channel broadcasts about history?", options: ["HTV", "Channel 4 Wales", "TSW", "no channel at all"], answer: 2 }, { q: "Where does Ken’s father live?", options: ["in the City centre", "in Matlock village", "in Gate Lane", "near a motorway"], answer: 2 }, { q: "What is being advertised?", options: ["a luxury hotel", "a fitness centre", "a summer camp", "a restaurant"], answer: 0 }, { q: "You are flying to New York. Where should passengers to New York go?", options: ["to terminal B", "to the departure lounge", "to luggage collection", "to the exits"], answer: 1 }, { q: "What is it true about Georgina Curry?", options: ["She went to Jakarta for an appendix operation.", "She is going to Jakarta for an appendix operation.", "She went to Jakarta on her honeymoon.", "She is going to Jakarta on her honeymoon"], answer: 3 }] } ], },
    { n: 2, title: "Part 2", hint: HINTS[2], recordings: [
      { id: "listening-48-p2", label: "Bài nghe Part 2", audio: "https://cdn.thanhnamnguyen.dev/vstep/audio/listening/listening-18/part1-2.mp3", script: "Conversation 1 (Q.9-12)\nM: And today, I’m talking to Angela Morgan. Angela, what made you decide to fly round the world in a helicopter?\nW: People often ask me why I decided to do it but I’m surprised they don’t ask ‘Why did you wait so long?’ because I’m 57 now. I’m sorry I didn’t do it years ago, because it was such a wonderful experience. But the main purpose for going was to collect 500,000 pounds for sick children by getting different companies to pay us money for each kilometre that we flew.\nM: And now everyone calls you the flying grandmother!\nW: Yes, the thing about growing older is that you don’t feel any different inside so you have to do as much as you can while you can. I’m healthy, and my own children are grown up, so I was free to go.\nM: And what about preparing for the trip?\nW: Well, it took five months to plan. I was going to go with my husband but he couldn’t take time off work. Instead, I made the trip with my flying teacher who became a great friend while she was teaching me to fly three years ago. I passed my flying test after two weeks; found it quite easy.\nM: And what was the trip like?\nW: It was really exciting flying over so many different countries. The only thing was that we weren’t able to spend much time sightseeing because we only stopped to get water and to camp. We took very little with us but we did have tents and cooking things to use at night. We had to spend two days in Thailand because of an engine problem but that was the longest we spent anywhere. Fortunately nothing else went wrong, so we just kept on going after that.\nM: What did you enjoy most about the trip?\nW: The most wonderful thing about flying was seeing the differences in the countryside as we flew across 26 countries in 97 days. We flew over oceans and close to mountains; sometimes it was quite frightening, but we didn’t travel when it was dark. We spent several nights camping in the desert and the sky was just full of stars. I made a video of the trip; you’ll see it in a minute.\nM: Was there anything that you missed while you were away?\nW: Well, to my surprise I didn’t miss going to work or going out to restaurants or films. The most difficult thing was sitting still all the time. I normally play tennis and swim several times a week, so I started to feel very unfit. I missed hot water and proper showers sometimes too, but not as much as I thought I would!\nConversation 2 (Q.13-16)\nM: Britta, you’re English, but you live in Berlin. Have you lived here for a long time?\nW: Well, I was born in England, but I’ve lived in Germany for the past twenty years. I arrived in Berlin about four years ago. Before that, I lived in Bonn for six years, but I work as a journalist and when the newspaper moved to Berlin, I moved with them.\nM: Were you pleased to come to Berlin?\nW: Yes, I was. I was looking forward to being in a big city like Berlin. Bonn was quite a lot smaller, so I love the busy atmosphere and all the cultural entertainments here museums, theatres and so on. The only thing I don’t like is the traffic it’s a bit noisy in the mornings. It wakes me up about 6.30, but most days I have to get up early anyway!\nM: Where do you live in Berlin?\nW: I have a flat in the old part of the city. It’s right in the centre and it’s not too expensive. It costs me about 500 pounds a month. My street is becoming very popular. There are lots of new art galleries, and small cafés and friendly restaurants everywhere. Eating out in Berlin is fun, and it’s cheap, so it’s something I do quite often.\nM: How do you find transport in Berlin?\nW: Well, the transport system here is very good, so I have a tram and bus ticket but in fact, most of the time I cycle. Travel here is much cheaper than in other countries I know perhaps that’s why people don’t walk very much!\nM: What do you like to do in Berlin at the weekends?\nW: Well, I like art, so sometimes I go to one of the galleries. I have a nephew called Philippe. He’s only three but he likes coming with me. He likes the café best, I think. And it’s a change from going to the park that’s something he does very often. He usually comes out with me while his parents go shopping.\nM: Do you miss your friends and family in England?\nW: I don't really miss England, most of my friends are here. I don't see much of my work colleagues socially, but I've got some very good friends who live in the same street as me. I enjoy meeting people, and I find Berlin is a very friendly city.\nM: Thank you for talking to us, Britta.\nConversation 3 (Q.17-20)\nM: Rachel, tell us how your shows for children started. You studied art at college, didn’t you?\nW: That’s right. But I gave up my career as an artist when my twin daughters were born. Painting took up too much time when I was looking after them. I thought about teaching art classes part-time, but instead I started making dolls for my daughters. I love acting, so I often invented little plays for the dolls, doing the voices myself.\nM: And when did you start doing shows for other people?\nW: When our daughters were five, my husband suggested using the dolls to entertain the children at their birthday party. I wrote a little show and he built a dolls’ theatre. My daughters and their friends loved it. As a result, other parents asked me to come and do the show at their children’s parties. That’s how it all began.\nM: It must be a lot of work for you?\nW: Yes. I love making the dolls, but I decided that I needed someone to help me with the shows. Luckily my neighbour, Lena, was keen to perform with me. Her husband records the music to go with the shows. It would be impossible to do everything on my own.\nM: Have you ever had any problems?\nW: Only once. I did a show for a group of three year olds, and I’d written a story about a lion. Unfortunately, the children were really afraid of the lion and started crying. I was worried the parents might complain but luckily they were all able to laugh about it afterwards.\nM: And what did you learn from that?\nW: The experience taught me that I had to find out beforehand just what children enjoy. Like me, Lena has two daughters, so whenever we’ve invented a new story we show it to our four girls first. They always tell us exactly what they think of it. And sometimes I take new dolls to the local primary school to check that children like them.\nM: And the shows continue to be successful?\nW: They do. I have a range of different shows for five to nine year olds. In fact, the shows have become so successful I could do one every day, but I don’t want to do that. The reason the shows have become popular, I think, is because I love every minute of every show and so other people love them too. I certainly didn’t realise when I organised that birthday party for my daughters all those years ago that it would change my life so much!", questions: [{ q: "Why does Angela feel she should do as much as she can?", options: ["She wants to make up for lost opportunities.", "She wants to stay active while she still can.", "She feels responsible for helping her children.", "She wants to prove that age is not a problem."], answer: 1 }, { q: "What does Angela say about learning to fly?", options: ["She needed several months to pass the test.", "She learned to fly mainly from her husband.", "She became close friends with her instructor.", "She found the flying test difficult to pass."], answer: 2 }, { q: "What did Angela enjoy most during the flight?", options: ["Seeing how the landscapes changed.", "Camping under the desert stars.", "Visiting different countries on foot.", "Flying close to the mountains."], answer: 0 }, { q: "What did Angela miss most during the trip?", options: ["Eating at restaurants regularly.", "Having hot water for showers.", "Keeping up her usual exercise.", "Watching films in the evenings."], answer: 2 }, { q: "Why did Britta move to Berlin?", options: ["She wanted to live in a larger city.", "She was offered work by a Berlin newspaper.", "Her newspaper moved its offices there.", "She wanted to be closer to German friends."], answer: 2 }, { q: "What does Britta particularly enjoy about Berlin?", options: ["Its quieter streets and cheaper housing.", "Its lively atmosphere and cultural activities.", "Its convenient transport and cycling routes.", "Its friendly cafés and local restaurants."], answer: 1 }, { q: "How does Britta usually travel around Berlin?", options: ["She mainly uses public transport.", "She often walks to nearby places.", "She usually drives her own car.", "She usually travels by bicycle."], answer: 3 }, { q: "What does Britta say about her social life in Berlin?", options: ["She mainly spends time with work colleagues.", "She often meets friends who live nearby.", "She still keeps most friendships in England.", "She usually spends weekends with her nephew."], answer: 1 }, { q: "What did Rachel do before becoming a mother?", options: ["She worked as an art teacher.", "She performed in children's theatre.", "She made dolls for children's shows.", "She worked as a professional artist."], answer: 3 }, { q: "Who first suggested using the dolls at a party?", options: ["Rachel's husband", "Rachel's daughters", "Rachel's neighbours", "The children's parents"], answer: 0 }, { q: "What does Lena do during Rachel's shows?", options: ["She performs together with Rachel.", "She builds the theatre for each show.", "She creates the music for each performance.", "She records the shows for the children."], answer: 0 }, { q: "How do Rachel's daughters help prepare new shows?", options: ["They perform new stories at their school.", "They help Rachel design new dolls.", "They give feedback on new stories.", "They choose the music for each show."], answer: 2 }] } ], },
    { n: 3, title: "Part 3", hint: HINTS[3], recordings: [
      { id: "listening-48-p3", label: "Bài nghe Part 3", audio: "https://cdn.thanhnamnguyen.dev/vstep/audio/listening/listening-04/part1-3.mp3", script: "Talk/Lecture 1\nYoung people in Great Britain are watching less and less news on television. This is according to Ofcom, a regulatory body that oversees broadcasting practices in the UK. This comes as no surprise as young people become increasingly addicted to their smartphones. Youth are opting for online distractions like YouTube videos, social media and games rather than switch on a TV and watch a news programme. Britain's Guardian newspaper reported that: \"The youth of the nation are more likely to get their day's news about the world from social media or by reading graffiti in bus stations than seeing it on the telly, with the average 16-24-year-old watching just two minutes' worth of live TV news per day.\"\nOfcom commissioned research into the news-viewing habits of people around the country. The report is called \"News Consumption in the UK: 2019\". The research suggests that young people are increasingly using social media as their primary news source. Researchers wrote: \"There is evidence that UK adults are consuming news more actively via social media.\" They reported an increase in posts and comments on Facebook and Twitter about the news compared to last year. Ofcom suggested presenting news stories in a less complicated, more accessible way to attract young people's attention. Some people suggested this would be \"dumbing down content for young audiences\".\nTalk/Lecture 2\nThere has been a dramatic increase in the popularity of veganism around the world in the past decade. Many people are becoming vegans in an attempt to lead a lifestyle that is more conducive to helping the planet. Giving up eating meat, dairy and other food from animals constitutes the bulk of changes vegans make to their lives. However, an increasing number of vegans are now extending their beliefs to fashion. There is a considerable increase in the sales of vegan clothing, footwear and accessories. Retailers are marketing products that are free from cow skin and other animal products. Shops are full of synthetic fur coats, plastic belts, and shoes made from tree bark, recycled plastic bottles, rubber and coconut fibre.\nResearch in the United Kingdom revealed that 42 per cent of shoppers considered animal welfare before buying clothes. The researchers discovered that people of all ages would consider purchasing vegan footwear. The trend in vegan fashion has also reached luxury brands. Designer Stella McCartney has designed a new range of fashion that is free from leather and makes use of recycled products. Her new collection is based on a theme of the iconic sixties pop group the Beatles. Ms McCartney's father, Paul, was lead singer of the group. She has designed leather-free Yellow Submarine sneakers and colourful fake fur coats. Ms McCartney is a committed animal rights activist.\nTalk/Lecture 3\nAlan Turing, the man widely recognised as being the father of modern computer science, has been honored by being selected to appear on a United Kingdom banknote. Mr Turing was chosen ahead of a wealth of notable British historical figures and luminaries to be the face of the new 50 Pound note. Turing was instrumental in helping Britain and its allies win World War II. He led a team of codebreakers to crack the Enigma code the Nazis used to send messages to warships and military commanders. He invented the now famous British Bombe to do this. This was a giant computer, which ushered in the birth of modern computing and the beginnings of artificial intelligence.\nAlan Turing was a mathematical genius who also excelled in the sciences. He was born in London in 1912. He graduated from Cambridge University and then outlined his vision for creating an algorithm-based computing machine. He said of his invention: \"This is only a foretaste of what is to come, and only the shadow of what is going to be.\" His idea is central to the computers we use today. His brilliance led to his being asked to join the WWII code-breaking team. Despite his pivotal role in ending that war, he was persecuted in the post-war years for being homosexual. Being gay was illegal in the UK until 1967. He chose to be chemically castrated rather than go to prison. Turing died in 1954, aged 41, in an apparent suicide.\nNguồn: https://vstepowl.com/listening/de-thi/?exam=listening-48", questions: [{ q: "Why, according to the passage, has TV news-watching fallen among young Britons?", options: ["They now prefer spending time on smartphone-based entertainment.", "They believe social media reports the news more accurately.", "They find television news too complicated to follow.", "They get most of their information from printed sources instead."], answer: 0 }, { q: "What point is the Guardian making by comparing social media and graffiti to television news?", options: ["That newspapers remain a more reliable source than either alternative.", "That graffiti has become an officially recognised source of news.", "That television has become a minor source of news for young people.", "That reading in public places has become more popular than social media."], answer: 2 }, { q: "What does the two-minute figure indicate about young people's use of television news?", options: ["They watch live news only occasionally compared with other sources.", "They spend about two minutes watching news for every hour of television.", "They have reduced their television news viewing by two minutes since last year.", "They normally watch two minutes of news before switching to social media."], answer: 0 }, { q: "What does the research suggest about news consumption beyond just young people?", options: ["That older adults are also increasingly using social media for news.", "That social media use for news has decreased since the previous year.", "That older adults still strongly prefer traditional broadcast news.", "That the research focused mainly on the habits of teenagers."], answer: 0 }, { q: "What is implied by the criticism that Ofcom's proposal is 'dumbing down' the news?", options: ["That young audiences specifically requested simpler news formats.", "That simplifying news content might reduce its depth or quality.", "That Ofcom plans to stop reporting international news entirely.", "That the criticism fully supports Ofcom's proposed approach."], answer: 1 }, { q: "What does the growth of vegan fashion suggest about how veganism has evolved?", options: ["That fashion brands invented veganism mainly as a marketing strategy.", "That vegan fashion has replaced diet as the movement's main focus.", "That it has expanded from a diet into a wider lifestyle movement.", "That most vegans still refuse to buy clothing made from animal products."], answer: 2 }, { q: "Why are retailers increasingly marketing clothing free from animal-based materials?", options: ["Because new regulations now prohibit the use of leather.", "Because animal-based materials have become too costly to produce.", "Because synthetic materials are always cheaper than natural fibres.", "To respond to growing ethical and environmental concerns among consumers."], answer: 3 }, { q: "What does the range of materials used in vegan footwear illustrate?", options: ["Vegan fashion depends mainly on recycled plastic products.", "Non-animal materials can come from a wide range of sources.", "Most vegan footwear is made from materials originally used in construction.", "Natural materials are gradually replacing synthetic ones in vegan fashion."], answer: 1 }, { q: "What does the research suggest about the potential market for vegan footwear?", options: ["It may appeal to consumers across different age groups.", "It is mainly limited to shoppers who already follow vegan diets.", "It is likely to remain a small market because most shoppers reject vegan products.", "It mainly attracts older shoppers concerned about animal welfare."], answer: 0 }, { q: "What does the choice of a Beatles theme for Stella McCartney's collection suggest?", options: ["That she drew on her family's connection to the band.", "That the Beatles themselves promoted vegan fashion in the sixties.", "That the collection was designed together with the band's members.", "That she chose the theme purely because of its commercial popularity."], answer: 0 }, { q: "Why, most likely, was Turing chosen for the banknote ahead of other historical figures?", options: ["Because he was the only mathematician being considered for the note.", "Because he was more famous to the public than all the other candidates.", "Because of his foundational impact on the development of modern computing.", "Because the Bank wanted to symbolically address his past persecution."], answer: 2 }, { q: "What was the main purpose of the British Bombe?", options: ["To help decode messages sent using the Enigma system.", "To replace the Enigma machine used by Allied forces.", "To study the mathematical theories behind modern computers.", "To send coded instructions to British military commanders."], answer: 0 }, { q: "What did Turing mean by calling his invention only a 'foretaste' and a 'shadow' of what was to come?", options: ["That the machine was flawed and would soon be forgotten.", "That its significance would become clearer through later developments.", "That he doubted computers would ever become widely used.", "That the design was mainly based on ideas from ancient science."], answer: 1 }, { q: "What does the passage suggest about how Turing was treated after the war, given his wartime role?", options: ["That his achievements did not protect him from persecution over his sexuality.", "That his wartime work was kept secret to protect his privacy.", "That he was publicly celebrated as a national hero immediately after the war.", "That the law against homosexuality was changed because of his case."], answer: 0 }, { q: "What does the passage suggest about the circumstances of Turing's death?", options: ["He died peacefully after retiring from academic life.", "He died from complications following a medical procedure.", "He remained imprisoned until his death because of his sexuality.", "He apparently died by suicide after years of persecution over his sexuality."], answer: 3 }] } ], },
  ] },
];
